package org.nonfood.oilplants.web;
import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import org.nonfood.oilplants.service.ImageStorage;import java.io.*;import java.nio.file.*;
@WebServlet("/image/*") public class ImageServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException{String name=r.getPathInfo()==null?"":r.getPathInfo().replaceFirst("^/","");try{if(!new org.nonfood.oilplants.dao.PlantDao().imageExists(name)){s.sendError(404);return;}Path p=ImageStorage.resolve(name);if(!Files.isRegularFile(p)){s.sendError(404);return;}String type=name.endsWith(".png")?"image/png":name.endsWith(".webp")?"image/webp":"image/jpeg";s.setContentType(type);s.setHeader("X-Content-Type-Options","nosniff");s.setHeader("Cache-Control","public,max-age=604800,immutable");Files.copy(p,s.getOutputStream());}catch(Exception e){s.sendError(404);}}}
